package com.bank.dedupe.service;

import com.bank.dedupe.dto.DuplicateGroup;
import com.bank.dedupe.model.CustomerRow;
import com.bank.dedupe.repository.CustomerRepository;

import java.util.*;
import java.util.logging.Logger;

public class DuplicateFinderService {
    private static final Logger log = Logger.getLogger(DuplicateFinderService.class.getName());
    private final CustomerRepository repo;
    public DuplicateFinderService(CustomerRepository repo) { this.repo = repo; }

    // Equivalent of: GROUP BY pan HAVING COUNT(*) > 1
    public List<DuplicateGroup> findDuplicatePans() {
        Map<String, Long> counts = new LinkedHashMap<>();
        for (CustomerRow r : repo.findAll()) {
            // normalize key like LOWER(TRIM(pan)) would in SQL
            String key = r.getPan().trim().toUpperCase();
            counts.merge(key, 1L, Long::sum); // COUNT(*) per pan
        }
        List<DuplicateGroup> result = new ArrayList<>();
        for (Map.Entry<String, Long> e : counts.entrySet()) {
            if (e.getValue() > 1) {                      // HAVING COUNT(*) > 1
                result.add(new DuplicateGroup(e.getKey(), e.getValue()));
            }
        }
        result.sort((a, b) -> Long.compare(b.getCount(), a.getCount())); // ORDER BY cnt DESC
        log.warning(() -> "Found " + result.size() + " duplicate PAN group(s)");
        return result;
    }
}
