package com.bank.dedupe;

import com.bank.dedupe.dto.DuplicateGroup;
import com.bank.dedupe.repository.CustomerRepository;
import com.bank.dedupe.service.DuplicateFinderService;

public class DedupeApplication {
    public static void main(String[] args) {
        DuplicateFinderService service = new DuplicateFinderService(new CustomerRepository());
        System.out.println("DUPLICATE PAN   COUNT");
        for (DuplicateGroup g : service.findDuplicatePans()) {
            System.out.printf("%-14s  %d%n", g.getKey(), g.getCount());
        }
    }
}
